import unicodedata
def rw(c): return 2 if unicodedata.east_asian_width(c) in "WF" else 0 if unicodedata.category(c) in ("Mn","Me","Cf") else 1
def w(s): return sum(rw(c) for c in s)
def cut(s,a):
  if w(s)<=a: return s
  out="";x=0
  for c in s:
    if x+rw(c)>a-1: break
    out+=c;x+=rw(c)
  return out+"…"
def render(rows,W):
  col=max(w(l) for l,_,_ in rows)+3
  for l,d,n in rows:
    dd=d
    if W: dd=cut(d,W-col-(2+w(n) if n else 0))
    print(repr(l+" "*(col-w(l))+dd+("  "+n if n else "")))
